package com.vandorlabs.neoforge.gear;

import com.vandorlabs.neoforge.copifier.NativeCopiedSettingsValidation;
import com.vandorlabs.redstone.ChannelList;
import java.util.List;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;

/** Source semantic arm clipboard. Physical placement, target, payload and resource ownership stay local. */
public final class NativeGearCopiedSettings {
    private static final List<String> KEYS=List.of("FootFacing","MiddleHinge","HingeMode","KinkDirection","Direction","PushBlocks","RotatePayload","JoinArms","JoinRange","CarryLoad","LoadHeight","ActiveAngle","StartAngle","LandingAnglesVersion","ActiveExtension");
    public record Plan(boolean applicable,NativeGearSettings settings){}
    public static CompoundTag capture(NativeGearEntity root){return captureExact(root.settings().copied(root.assembly()!=null&&root.assembly().kind()!=com.vandorlabs.gear.core.GearTopology.FootKind.NONE));}
    public static CompoundTag capture(NativeGearSettings settings){return captureExact(settings.copied(false));}
    private static CompoundTag captureExact(NativeGearSettings settings){var out=new CompoundTag();var choices=settings.choices();var copied=new CompoundTag();for(var key:KEYS)copied.put(key,choices.get(key).copy());copied.putBoolean("LegacyAnyChannels",settings.legacyAnyChannels());out.put("modular_arm_settings",copied);out.putInt("redstone_trigger",settings.trigger());if(settings.channels().size()<=1)out.putInt("redstone_channel",settings.channels().first());else out.putIntArray("redstone_channel",settings.channels().toArray());return out;}
    public static Plan prepare(NativeGearSettings current,CompoundTag values){if(values==null||values.sizeInBytes()>256*1024||!NativeCopiedSettingsValidation.valid(values))throw new IllegalArgumentException("Malformed copied arm settings");boolean arm=values.contains("modular_arm_settings"),trigger=values.contains("redstone_trigger"),channels=values.contains("redstone_channel");if(!arm&&!trigger&&!channels)return new Plan(false,current);if(arm&&!values.contains("modular_arm_settings",Tag.TAG_COMPOUND)||trigger&&!values.contains("redstone_trigger",Tag.TAG_INT)||channels&&!values.contains("redstone_channel",Tag.TAG_INT)&&!values.contains("redstone_channel",Tag.TAG_INT_ARRAY))throw new IllegalArgumentException("Copied arm field type");var next=current.choices();var copied=values.getCompound("modular_arm_settings");for(var key:KEYS)if(copied.contains(key))next.put(key,copied.get(key).copy());if((copied.contains("StartAngle")||copied.contains("ActiveAngle"))&&!copied.contains("LandingAnglesVersion"))next.remove("LandingAnglesVersion");if(copied.contains("MiddleHinge",Tag.TAG_BYTE)&&!copied.contains("HingeMode"))next.remove("HingeMode");if(copied.contains("Direction",Tag.TAG_INT)&&!copied.contains("KinkDirection"))next.putInt("KinkDirection",copied.getInt("Direction"));if(copied.contains("TrackStyle"))throw new IllegalArgumentException("Tracks are not an arm setting on this platform");if(trigger)next.putInt("Trigger",values.getInt("redstone_trigger"));if(channels){var bank=values.contains("redstone_channel",Tag.TAG_INT_ARRAY)?ChannelList.of(values.getIntArray("redstone_channel")):ChannelList.of(values.getInt("redstone_channel"));next.putString("Channels",bank.toString());if(copied.contains("LegacyAnyChannels")){if(!copied.contains("LegacyAnyChannels",Tag.TAG_BYTE)||copied.getByte("LegacyAnyChannels")<0||copied.getByte("LegacyAnyChannels")>1)throw new IllegalArgumentException("Copied arm channel mode");next.putBoolean("LegacyAnyChannels",copied.getBoolean("LegacyAnyChannels"));}}return new Plan(true,NativeGearSettings.readChoices(next));}
    public static boolean available(NativeGearEntity root,ServerPlayer actor){if(root==null||actor==null||!(root.getLevel() instanceof ServerLevel level)||!level.getServer().isSameThread()||actor.level()!=level||!actor.isAlive()||actor.isSpectator()||root.inert()||!root.controller()||NativeGearFormation.at(level,root.getBlockPos())!=root||root.getBlockState()!=level.getBlockState(root.getBlockPos())||!root.completeMembers()||NativeGearJournal.busy(root))return false;for(BlockPos member:root.members())if(!NativeGearFormation.loaded(level,member)||com.vandorlabs.neoforge.ramp.NativeRampHeldOwners.blocked(level,member)||!level.mayInteract(actor,member)||!actor.mayUseItemAt(member,net.minecraft.core.Direction.UP,actor.getMainHandItem()))return false;return true;}
    public static boolean apply(NativeGearEntity root,ServerPlayer actor,Plan plan){if(!plan.applicable()||!available(root,actor))return false;if(!root.configure(plan.settings(),root.target()))return false;root.authorize(actor);return true;}
    private NativeGearCopiedSettings(){}
}
